/**
 * Behavioral checks for {@link CheckoutPriceCalculator}.
 */
public final class CheckoutPriceCalculatorTest {
    /**
     * Runs the checkout-price calculator's focused behavioral checks.
     *
     * @param arguments ignored command-line arguments
     */
    public static void main(String[] arguments) {
        CheckoutPriceCalculator calculator = new CheckoutPriceCalculator();

        assertEquals(
                "88.56",
                calculator.calculate("100.00", "0.20", "0.107", CheckoutPriceCalculator.ShippingMethod.STANDARD));
        assertEquals(
                "105.17",
                calculator.calculate("100.00", "0.20", "0.107", CheckoutPriceCalculator.ShippingMethod.EXPEDITED));
        assertEquals(
                "1.00",
                calculator.calculate("1.005", "0", "0", CheckoutPriceCalculator.ShippingMethod.STANDARD));
        assertEquals(
                "1.02",
                calculator.calculate("1.015", "0", "0", CheckoutPriceCalculator.ShippingMethod.STANDARD));
        assertThrows(
                IllegalArgumentException.class,
                () -> calculator.calculate("1e2", "0", "0", CheckoutPriceCalculator.ShippingMethod.STANDARD));
        assertThrows(
                IllegalArgumentException.class,
                () -> calculator.calculate("1", "1.01", "0", CheckoutPriceCalculator.ShippingMethod.STANDARD));
    }

    /**
     * Confirms that an action throws a particular exception type.
     *
     * @param expectedType exception type that must be thrown
     * @param action operation expected to fail
     */
    private static void assertThrows(Class<? extends Throwable> expectedType, Runnable action) {
        try {
            action.run();
        } catch (Throwable exception) {
            if (expectedType.isInstance(exception)) {
                return;
            }
            throw new AssertionError("Expected " + expectedType.getName(), exception);
        }
        throw new AssertionError("Expected " + expectedType.getName());
    }

    /**
     * Confirms that two string values are equal.
     *
     * @param expected expected value
     * @param actual actual value
     */
    private static void assertEquals(String expected, String actual) {
        if (!expected.equals(actual)) {
            throw new AssertionError("Expected " + expected + " but was " + actual);
        }
    }
}

